abstract class Shape {
    abstract double area();
    void printArea() { System.out.println(area()); }
}

class Circle extends Shape {
    private final double radius;
    Circle(double radius) { this.radius = radius; }
    @Override
    double area() { return Math.PI * radius * radius; }
}

public class Main {
    public static void main(String[] args) {
        Shape shape = new Circle(2);
        shape.printArea();
    }
}

interface NotificationSender {
    void send(String message);
}

class EmailSender implements NotificationSender {
    public void send(String message) {
        System.out.println("Email: " + message);
    }
}

class SmsSender implements NotificationSender {
    public void send(String message) {
        System.out.println("SMS: " + message);
    }
}

class AlertService {
    private final NotificationSender sender;
    AlertService(NotificationSender sender) { this.sender = sender; }
    void alert(String message) { sender.send(message); }
}

public class Main {
    public static void main(String[] args) {
        AlertService service = new AlertService(new SmsSender());
        service.alert("Server is down");
    }
}
